INSERT INTO public.familias_quimicas (nome, descricao, exemplos) VALUES
('Surfactantes', 'Moléculas anfifílicas que reduzem a tensão superficial entre dois líquidos ou entre líquido e sólido. Presentes em produtos de limpeza e espumantes.', ARRAY['Sodium Lauryl Sulfate', 'Cocamidopropyl Betaine', 'Decyl Glucoside', 'Sodium Cocoyl Isethionate']),
('Emolientes', 'Substâncias que suavizam e amaciam a pele, preenchendo os espaços intercelulares da camada córnea. Originam-se de fontes vegetais, animais ou sintéticas.', ARRAY['Cetyl Alcohol', 'Stearyl Alcohol', 'Isopropyl Myristate', 'C12-15 Alkyl Benzoate', 'Squalane']),
('Emulsificantes', 'Substâncias capazes de manter em mistura estável substâncias imiscíveis (óleo e água). Classificados por HLB (Hydrophilic-Lipophilic Balance).', ARRAY['Cetearyl Alcohol', 'Polysorbate 20', 'Polysorbate 80', 'Lecithin', 'PEG-100 Stearate', 'Glyceryl Stearate SE']),
('Polímeros e Espessantes', 'Macromoléculas que aumentam a viscosidade de formulações aquosas ou oleosas. Podem ser naturais, semissintéticos ou sintéticos.', ARRAY['Carbomer', 'Hydroxyethylcellulose', 'Xanthan Gum', 'Acrylates Copolymer', 'Carrageenan', 'Guar Gum']),
('Conservantes', 'Sistema de preservação que protege formulações contra contaminação microbiana. A escolha impacta segurança, estabilidade e aceitação pelo consumidor.', ARRAY['Phenoxyethanol', 'Sodium Benzoate', 'Potassium Sorbate', 'Ethylhexylglycerin', 'Benzyl Alcohol', 'Chlorphenesin']),
('Antioxidantes', 'Substâncias que previnem a oxidação de ingredientes suscetíveis (óleos, vitaminas, ativos instáveis). Aumentam a vida útil da formulação e protegem a pele dos radicais livres.', ARRAY['Tocopherol', 'Tocopheryl Acetate', 'Ascorbyl Glucoside', 'BHT', 'Rosmarinus Officinalis Leaf Extract']),
('Quelantes', 'Compostos que formam complexos estáveis com íons metálicos (Ca²⁺, Mg²⁺, Fe²⁺), evitando que catalisem reações de oxidação ou inativem conservantes.', ARRAY['Disodium EDTA', 'Tetrasodium EDTA', 'Phytic Acid', 'Sodium Phytate', 'Citric Acid']),
('Umectantes e Hidratantes', 'Substâncias higroscópicas que retêm água na pele, reduzindo a perda transepidérmica de água (PTEA/TEWL). Atuam na camada córnea e abaixo dela.', ARRAY['Glycerin', 'Sodium Hyaluronate', 'Hyaluronic Acid', 'Panthenol', 'Sorbitol', 'Sodium PCA', 'Urea']),
('Oclusivos', 'Substâncias que formam filme físico sobre a pele, impedindo mecanicamente a evaporação de água. Complementam a ação de umectantes.', ARRAY['Petrolatum', 'Dimethicone', 'Cyclopentasiloxane', 'Beeswax', 'Mineral Oil', 'Lanolin']),
('Filtros Ultravioleta', 'Compostos capazes de absorver, refletir ou dispersar a radiação UV (UVA e/ou UVB), protegendo a pele dos danos actínicos.', ARRAY['Zinc Oxide', 'Titanium Dioxide', 'Ethylhexyl Methoxycinnamate', 'Avobenzone', 'Tinosorb M', 'Tinosorb S', 'Uvinul A Plus']),
('Ativos Despigmentantes', 'Substâncias que interferem em diferentes etapas da melanogênese, reduzindo a produção e distribuição de melanina. Usadas no tratamento de hiperpigmentação.', ARRAY['Niacinamide', 'Alpha-Arbutin', 'Kojic Acid', 'Azelaic Acid', 'Tranexamic Acid', 'Ascorbic Acid', 'Resorcinol']),
('Ativos Anti-Aging', 'Substâncias que combatem os sinais do envelhecimento cutâneo através de diferentes mecanismos: estimulação de colágeno, renovação celular, antioxidação.', ARRAY['Retinol', 'Retinyl Palmitate', 'Bakuchiol', 'Matrixyl 3000', 'Argireline', 'DMAE', 'Idebenone']),
('Vitaminas', 'Micronutrientes essenciais com ação funcional na pele quando aplicados topicamente. Incluem vitaminas lipossolúveis e hidrossolúveis com diferentes mecanismos de ação.', ARRAY['Vitamin C (Ascorbic Acid)', 'Vitamin E (Tocopherol)', 'Vitamin B3 (Niacinamide)', 'Vitamin B5 (Panthenol)', 'Vitamin A (Retinol)', 'Vitamin B12']),
('Ácidos Exfoliantes (AHAs, BHAs, PHAs)', 'Ácidos orgânicos que promovem renovação celular através de esfoliação química. AHAs: hidrofílicos (glicólico, lático). BHAs: lipofílicos (salicílico). PHAs: renovação mais suave.', ARRAY['Glycolic Acid', 'Lactic Acid', 'Mandelic Acid', 'Salicylic Acid', 'Gluconolactone', 'Lactobionic Acid', 'Citric Acid']),
('Proteínas e Aminoácidos', 'Macromoléculas e seus monômeros que fortalecem a barreira cutânea, hidratam e condicionam pele e cabelo. Podem ser hidrolisados para melhor penetração.', ARRAY['Hydrolyzed Collagen', 'Hydrolyzed Keratin', 'Hydrolyzed Silk', 'Wheat Amino Acids', 'Arginine', 'Proline']),
('Óleos e Manteigas Vegetais', 'Lipídios de origem vegetal ricos em ácidos graxos insaturados, vitaminas lipossolúveis e fitoesteróis. Emolientes naturais com perfis funcionais distintos.', ARRAY['Rosa Canina Fruit Oil', 'Simmondsia Chinensis (Jojoba) Seed Oil', 'Butyrospermum Parkii (Shea) Butter', 'Calophyllum Inophyllum Seed Oil', 'Hippophae Rhamnoides Fruit Oil']),
('Silicones', 'Polímeros de silício e oxigênio com propriedades únicas: sensorial suave (slip), formação de filme, termotolerância. Amplamente usados em cuidado capilar e maquiagem.', ARRAY['Dimethicone', 'Cyclopentasiloxane', 'Cyclohexasiloxane', 'Amodimethicone', 'Caprylyl Methicone', 'PEG/PPG-18/18 Dimethicone']),
('Ativos Anti-Acne e Seboreguladores', 'Substâncias com ação comedolítica, antiséptica, anti-inflamatória ou reguladora da produção sebácea. Atuam em diferentes etapas da cascata acneica.', ARRAY['Salicylic Acid', 'Niacinamide', 'Zinc PCA', 'Azelaic Acid', 'Tea Tree Oil', 'Benzoyl Peroxide']),
('Calmantes e Anti-Inflamatórios', 'Substâncias que reduzem vermelhidão, irritação e inflamação cutânea. Indicadas para peles sensíveis, reativas e pós-procedimento.', ARRAY['Bisabolol', 'Allantoin', 'Centella Asiatica Extract', 'Aloe Barbadensis Leaf Juice', 'Licorice Root Extract', 'Oat Extract (Avena Sativa)']),
('Peptídeos', 'Pequenas sequências de aminoácidos com ação biológica específica na pele. Podem ser mensageiros, portadores de ativos, bloqueadores neuromusculares ou estimuladores de matriz.', ARRAY['Palmitoyl Tripeptide-1', 'Palmitoyl Tetrapeptide-7', 'Acetyl Hexapeptide-3 (Argireline)', 'Copper Tripeptide-1', 'Leuphasyl', 'Syn-Ake']),
('Ceramidas e Lipídios de Barreira', 'Lipídios essenciais da barreira cutânea que reconstituem o cemento intercelular da camada córnea, reduzindo a PTEA e restaurando a integridade da barreira.', ARRAY['Ceramide NP', 'Ceramide AP', 'Ceramide EOP', 'Cholesterol', 'Phytosphingosine', 'Linoleic Acid']),
('Extratos Botânicos', 'Misturas complexas de compostos bioativos obtidas de plantas, flores, frutas ou sementes. Apresentam amplo espectro de atividades (antioxidante, anti-inflamatória, etc.).', ARRAY['Calendula Officinalis Extract', 'Chamomilla Recutita Extract', 'Green Tea Extract (Camellia Sinensis)', 'Pomegranate Extract', 'Turmeric Extract'])
